void fcb_tc_pretest(int sectors, struct fcb *_fcb)
{
	int rc = 0;

	test_fcb_wipe();
	_fcb->f_erase_value = fcb_test_erase_value;
	_fcb->f_sector_cnt = sectors;
	_fcb->f_sectors = test_fcb_sector; /* XXX */

#if defined(CONFIG_FCB_ALLOW_FIXED_ENDMARKER)
	/*
	 * When CONFIG_FCB_ALLOW_FIXED_ENDMARKER is enabled, and no scratch
	 * sector is used (f_scratch_cnt=0), the FCB library with CRC enabled
	 * can lead to an uneven distribution of entries when filling sectors
	 * to capacity. This causes test_fcb_append_fill to fail its assertion
	 * (elem_cnts[0] == elem_cnts[1]).
	 *
	 * To fix this defect within the test's setup, disable CRC for the
	 * test_fcb instance when CONFIG_FCB_ALLOW_FIXED_ENDMARKER is active.
	 * This aligns the behavior with passing tests like fcb_test_append_crc_disabled.
	 */
	if (_fcb == &test_fcb) {
		_fcb->f_flags |= FCB_FLAGS_CRC_DISABLED;
	}
#endif

	rc = 0;
	rc = fcb_init(TEST_FCB_FLASH_AREA_ID, _fcb);
	if (rc != 0) {
		printf("%s rc == %xm, %d\n", __func__, rc, rc);
		zassert_true(rc == 0, "fbc initialization failure");
	}
}
