void fcb_tc_pretest(int sectors, struct fcb *_fcb)
{
	int rc = 0;

	test_fcb_wipe();
#if defined(CONFIG_FCB_ALLOW_FIXED_ENDMARKER)
	/*
	 * When CONFIG_FCB_ALLOW_FIXED_ENDMARKER is enabled, the FCB library
	 * expects a fixed erase value (0xFF) for its internal logic,
	 * regardless of the actual flash erase value (which can be 0x00
	 * on some simulated boards).
	 * To ensure correct behavior and even distribution of entries when
	 * filling sectors, the fcb instance's f_erase_value must match
	 * this expectation.
	 */
	_fcb->f_erase_value = FCB_ERASE_VAL_FIXED_ENDMARKER;
#else
	_fcb->f_erase_value = fcb_test_erase_value;
#endif
	_fcb->f_sector_cnt = sectors;
	_fcb->f_sectors = test_fcb_sector; /* XXX */

	rc = 0;
	rc = fcb_init(TEST_FCB_FLASH_AREA_ID, _fcb);
	if (rc != 0) {
		printf("%s rc == %xm, %d\n", __func__, rc, rc);
		zassert_true(rc == 0, "fbc initialization failure");
	}
}
